data./financialHealth/schema.diagx:
/// financialhealth kind. VS Code highlight preamble.

<schema>
  <diagx-section id="summary" position="left" title="Summary" separator={false} showMore="summary">
    <diagx-row gap="md">
      <diagx-column span={12} md={6} lg={3}>
        <diagx-summarycard
          anchor="household"
          Icon="HouseholdLogo"
          title="Household"
          label={
            $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName")
              ? $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName") +
                " (" +
                $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientAge", "") +
                ")"
              : ""
          }
          secondLabel={
            $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "")
              ? $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "") +
                " (" +
                $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientAge", "") +
                ")"
              : ""
          }
        />
      </diagx-column>
      <diagx-column span={12} md={6} lg={3}>
        <diagx-summarycard
          anchor="income"
          Icon="IncomeLogo"
          title="Income"
          label={
            $.get("/client/financialhealth_keymetrics.json", "assetsAndInvestments.incomeAndTaxation.clientGrossIncome", 0)
              ? $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName") +
                " " +
                $.format($.get("/client/financialhealth_keymetrics.json", "assetsAndInvestments.incomeAndTaxation.clientGrossIncome", 0), {
                  style: "currencyCompact",
                })
              : ""
          }
          secondLabel={
            $.get("/client/financialhealth_keymetrics.json", "assetsAndInvestments.incomeAndTaxation.coClientGrossIncome", 0)
              ? $.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "") +
                " " +
                $.format($.get("/client/financialhealth_keymetrics.json", "assetsAndInvestments.incomeAndTaxation.coClientGrossIncome", 0), {
                  style: "currencyCompact",
                })
              : ""
          }
        />
      </diagx-column>
      <diagx-column span={12} md={6} lg={3}>
        <diagx-tooltipwrapper
          content="Net worth is the financial value that represents the difference between your assets and total liabilities. It serves as a measure of financial success and stability."
          side="top"
        >
          <diagx-summarycard
            anchor="net-worth"
            Icon="NetWorthLogo"
            title="Net worth"
            label={`${$.format($.get("/client/financialhealth_keymetrics.json", "netWorthStatement.netWorth.total", 0), { style: "currencyCompact" })} total`}
            secondLabel={`${$.format($.get("/client/financialhealth_keymetrics.json", "ratios.investableAssetLevel.investableAssets", 0), { style: "currencyCompact" })} investable assets`}
          />
        </diagx-tooltipwrapper>
      </diagx-column>
      <diagx-column span={12} md={6} lg={3}>
        <diagx-summarycard
          anchor="debt"
          Icon="DebtLogo"
          title="Debt"
          label={`${$.format($.get("/client/financialhealth_keymetrics.json", "debtManagement.debtOverview.debtBalance", 0), { style: "currencyCompact" })} balance`}
          secondLabel={`${$.format($.get("/client/financialhealth_keymetrics.json", "debtManagement.debtToIncomeAndMonthlyObligations.monthlyDebtPayments", 0), { style: "currencyCompact" })} monthly payment`}
        />
      </diagx-column>
    </diagx-row>
    <diagx-editable-blurbs id="summary_main" agentGenerated advises={generation} />
    <diagx-recommendations
      title="Recommendations"
      id="summary_recommendations"
      agentGenerated
      recommendations={generation}
    />
  </diagx-section>
  <diagx-section id="retirement" title="Retirement & Goals" separator showMore="retirement">
    <diagx-goalslist
      anchor="goals-list"
      goals={$.get("/client/financialhealth_derived.json", "retirementAndGoals.goalsSummary")}
      chartGoals={$.get("/client/financialhealth_derived.json", "retirementAndGoals.chartGoals")}
    />
    <diagx-goaltimelinechart
      anchor="goal-timeline"
      areaKeys={["idealRealNetWorth", "realNetWorth"]}
      xDataKey="year"
      currentNetWorth={$.get("/client/networth.json", "projected")}
      birthDate={$.get("/client/profile.json", "head.birthDate", null)}
      chartGoals={$.get("/client/financialhealth_derived.json", "retirementAndGoals.chartGoals")}
      simulatedNetWorth={$.get("/client/networth.json", "whatYouNeed", [])}
      currentNetWorthValue={$.get("/client/financialhealth_keymetrics.json", "netWorthStatement.netWorth.total")}
      headAge={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientAge", "")}
      spouseAge={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientAge", "")}
    />
    <diagx-editable-blurbs
      id="retirement_short_observations"
      agentGenerated
      advises={generation}
    />
    <diagx-callout
      id="retirement_what_to_look_into"
      agentGenerated
      label={generation}
    />
  </diagx-section>
  <diagx-section id="assets" title="Assets & Investments" separator showMore="assetsAndInvestments">
    <diagx-editable-blurbs
      id="assets_short_observations"
      agentGenerated
      advises={generation}
      floatChildren={{ align: "left" }}
    >
      <diagx-assetstable
        anchor="assets-table"
        label="Assets"
        totalValue={$.get("/client/financialhealth_keymetrics.json", "netWorthStatement.assets.total")}
        items={$.get("/client/financialhealth_derived.json", "assetsAndInvestments.assets")}
        netWorthAssets={$.get("/client/financialhealth_keymetrics.json", "netWorthStatement.assets.items")}
      />
    </diagx-editable-blurbs>
    <diagx-callout
      id="assets_what_to_look_into"
      agentGenerated
      label={generation}
    />
  </diagx-section>
  <diagx-section id="debt" title="Debt management" separator showMore="debtManagement">
    <diagx-editable-blurbs
      id="debt_short_observations"
      agentGenerated
      advises={generation}
      floatChildren={{ align: "right" }}
    >
      <diagx-debtslider>
        <diagx-debt-overview
          anchor="debt-overview"
          total={$.get("/client/financialhealth_keymetrics.json", "debtManagement.debtOverview.debtBalance")}
          liabilities={$.get("/client/financialhealth_derived.json", "debtManagement.liabilities")}
          housingRatio={$.get("/client/financialhealth_keymetrics.json", "ratios.housingRatio.ratio")}
          debtToIncome={$.get("/client/financialhealth_keymetrics.json", "ratios.debtToIncome.ratio")}
          debtOnlyDti={$.get("/client/financialhealth_keymetrics.json", "ratios.debtToIncome.debtOnlyDti", null)}
          monthlyPayment={$.get("/client/financialhealth_keymetrics.json", "debtManagement.debtToIncomeAndMonthlyObligations.monthlyDebtPayments")}
          diagnostic={$.get("/client/financialhealth_derived.json", "debtManagement.diagnostic", null)}
        />
        <diagx-amortizationchart
          anchor="debt-amortization"
          amortizationTable={$.get("/client/networth.json", "amortization", null)}
          singleAmortizationTable={$.get("/client/networth.json", "singleAmortization", [])}
          singleAmortizationDetails={$.get("/client/financialhealth_derived.json", "debtManagement.singleAmortizationDetails", [])}
          birthDate={$.get("/client/profile.json", "head.birthDate", null)}
          headAge={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientAge", "")}
          spouseAge={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientAge", "")}
          projectedNetworth={$.get("/client/networth.json", "projected")}
          chartGoals={$.get("/client/financialhealth_derived.json", "retirementAndGoals.chartGoals")}
        />
      </diagx-debtslider>
    </diagx-editable-blurbs>
    <diagx-callout
      id="debt_what_to_look_into"
      agentGenerated
      label={generation}
    />
  </diagx-section>
  <diagx-section id="savings" title="Savings & Expenses" separator showMore="savingsAndExpenses">
    <diagx-cashflowchart
      anchor="cashflow-chart"
      headName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName")}
      spouseName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "")}
      clientIncome={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.inflows.client", "$0")}
      coClientIncome={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.inflows.coClient", "$0")}
      jointIncome={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.inflows.joint", "$0")}
      totalIncome={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.inflows.total", "$0")}
      freeCashFlow={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.freeCashflow.total", "$0")}
      outflowItems={$.get("/client/financialhealth_keymetrics.json", "cashflowStatement.outflows.items",[])}
    />
    <diagx-editable-blurbs
      id="savings_short_observations"
      agentGenerated
      advises={generation}
    />
    <diagx-callout
      id="savings_what_to_look_into"
      agentGenerated
      label={generation}
    />
  </diagx-section>
  <diagx-section id="protection" title="Insurance & Protection" separator>
    <diagx-editable-blurbs id="protection_intro" agentGenerated advises={generation} />
    <diagx-subsectiontitle id="section-emergency-fund" text="Emergency fund" showMore="showBlurbsEmergencyFund" className="mt-8" />
    <diagx-editable-blurbs
      id="protection_emergency_fund_short_observations"
      agentGenerated
      advises={generation}
      floatChildren={{ align: "right", className: "min-w-0 md:min-w-[35rem] pl-4 -mt-6 md:mt-0 mb-6 md:mb-0" }}
    >
      <diagx-protectionblock
        anchor="emergency-fund"
        color={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.color")}
        claim={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.claim")}
        type="SINGLE"
        chartTitle={`${$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.minRecommendedEmergencyFund")} - ${$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.maxRecommendedEmergencyFund")}`}
        max={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.maxRecommendedEmergencyFund")}
        min={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.minRecommendedEmergencyFund")}
        value={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.emergencyFund")}
        valueLabel={$.get("/client/financialhealth_keymetrics.json", "ratios.emergencyFund.emergencyFund")}
        headName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName")}
        spouseName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "")}
      />
    </diagx-editable-blurbs>
    <diagx-subsectiontitle id="section-life-insurance" text="Life insurance" showMore="showBlurbsLifeInsurance" />
    <diagx-editable-blurbs
      id="protection_life_insurance_short_observations"
      agentGenerated
      advises={generation}
      floatChildren={{ align: "right", className: "min-w-0 md:min-w-[35rem] pl-4 -mt-6 md:mt-0 mb-6 md:mb-0" }}
    >
      <diagx-protectionblock
        anchor="life-insurance"
        color={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.clientCoverageColor")}
        claim={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.clientCoverageKey")}
        type={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "") ? "MULTIPLE" : "SINGLE"}
        chartTitle={`${$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedClientMinCoverage")} - ${$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedClientMaxCoverage")}`}
        max={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedClientMaxCoverage")}
        min={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedClientMinCoverage")}
        value={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.clientCoverage")}
        valueLabel={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.clientCoverage")}
        spouseTitle={`${$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedCoClientMinCoverage")} - ${$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedCoClientMaxCoverage")}`}
        spouseColor={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.coClientCoverageColor")}
        spouseCoverage={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.coClientCoverage")}
        spouseMaxCoverage={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedCoClientMaxCoverage"
        )}
        spouseMinCoverage={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.recommendedCoClientMinCoverage"
        )}
        spouseClaim={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.coClientCoverageKey")}
        spouseValueLabel={$.get("/client/financialhealth_keymetrics.json", "ratios.lifeInsurance.coClientCoverage")}
        headName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.clientName")}
        spouseName={$.get("/client/financialhealth_keymetrics.json", "retirementAndOtherGoals.clientProfile.coClientName", "")}
      />
    </diagx-editable-blurbs>
    <diagx-subsectiontitle id="section-umbrella" text="Umbrella insurance" showMore="showBlurbsUmbrella" />
    <diagx-editable-blurbs
      id="protection_umbrella_short_observations"
      agentGenerated
      advises={generation}
      floatChildren={{ align: "right", className: "min-w-0 md:min-w-[35rem] pl-4 -mt-6 md:mt-0 mb-6 md:mb-0" }}
    >
      <diagx-protectionblock
        anchor="umbrella"
        color={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.color")}
        claim={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.claim")}
        chartTitle={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.recommendedCoverage")}
        max={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.recommendedCoverage")}
        min={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.recommendedCoverage")}
        value={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.currentCoverage")}
        valueLabel={$.get("/client/financialhealth_keymetrics.json", "ratios.umbrella.currentCoverage")}
      />
    </diagx-editable-blurbs>
  </diagx-section>
</schema>
